// App code: moving focus to the banner when it appears.
import type { Example } from "../example.ts"
import { html, type TemplateResult } from "lit-html"

export type ErrorBannerProps = {
  message: string
  action?: string
  onAction?: () => void
  class?: string
}

/** Apps put these classes on their own error banner. */
export function errorBannerClass(): string {
  return "px-4 py-3 rounded-surface border border-danger/40 bg-danger/10 text-sm text-danger-fg"
}

/** Apps put these classes on each action button inside the banner. */
export function errorBannerActionClass(): string {
  return "ml-2 rounded font-semibold underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-danger/40"
}

export function errorBanner(props: ErrorBannerProps): TemplateResult {
  const base = errorBannerClass()
  const classes = props.class === undefined ? base : `${base} ${props.class}`
  return html`<div role="alert" class=${classes}>
    ${props.message}${props.action === undefined ? undefined : html`<button type="button" class=${errorBannerActionClass()} @click=${props.onAction}>${props.action}</button>`}
  </div>`
}

export const examples: Example[] = [
  { label: "with action", render: () => errorBanner({ message: "Couldn't reach Nils. Their phone may be off.", action: "Retry" }) },
  { label: "without action", render: () => errorBanner({ message: "Couldn't reach Nils. Their phone may be off." }) },
]
